    correction: [{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">x - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - √2 = √3</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + √2 + √3</span>"},{"quoi":"نحدّد الإشارة","math":"العدد <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + √2 + √3</span> هو عدد موجب تقريبا يساوي 5.65"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد موجب هي هو نفسه، و لعدد سالب هي مقابله"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">|x| = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + √2 + √3</span>"}],
