    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">C = -x + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span> + √2 + √2 - 3 - √2 - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">5</span></span> + 2x + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">20</span></span> - 2√2</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">C = (-x + 2x) + (<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span> - 3 - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">20</span></span>) + (√2 + √2 - √2 - 2√2)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">C = x - 2 - √2</span>"}],
