    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">D = 2 + 3 + 4 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> + √3 - y - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - y - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + y - <span class=\"frac\"><span class=\"num\">101</span><span class=\"den\">12</span></span></span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">D = (-y - y + y) + (2 + 3 + 4 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">101</span><span class=\"den\">12</span></span>) + √3</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">D = -y - 1 + √3</span>"}],
