    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = -π + π + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> - b + 9 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + a - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">2</span></span> - π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = a - b + (<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + 9 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">2</span></span>) + (-π + π - π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = a - b + 2 - π</span>"}],
