    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span> - π - 4 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + 2 + 2 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - a + b - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span></span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = -a + b + (<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span> - 4 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + 2 + 2 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span>) - π</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -a + b - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - π</span>"}],
