    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">F = 4 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> + a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - b + 2b - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = a + (-b + 2b) + (4 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span>) + π</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = a + b - 2 + π</span>"}],
