    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> + a + 3 + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> - a - 3 - π - π - a + b - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + 3π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = (a - a - a) + b + (-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> + 3 + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> - 3 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span>) + (-π - π + 3π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -a + b + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + π</span>"}],
