    enonce: "أوجد <span dir=\"ltr\" class=\"expr\">a - b</span> إذا علمت أنّ M و N متساويان علما أنّ <span dir=\"ltr\" class=\"expr\">M = 2a + 3b + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + √2</span> و <span dir=\"ltr\" class=\"expr\">N = 3a + 2b - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + π</span>",
