    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = -b + 3 + 1 + 1 - b - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + 2a + 3b - <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">6</span></span> + √2</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = 2a + (-b - b + 3b) + (3 + 1 + 1 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">6</span></span>) + √2</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 2a + b - 2 + √2</span>"}],
