    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> - b + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> - √2 + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - 1 + 3a + 3b - <span class=\"frac\"><span class=\"num\">101</span><span class=\"den\">10</span></span></span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = 3a + (-b + 3b) + (<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - 1 - <span class=\"frac\"><span class=\"num\">101</span><span class=\"den\">10</span></span>) - √2</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 3a + 2b - <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - √2</span>"}],
