    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">N = -1 + π + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> + a + 1 + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + b + 1 + π + a + 2b - <span class=\"frac\"><span class=\"num\">143</span><span class=\"den\">30</span></span> - π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = (a + a) + (b + 2b) + (-1 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> + 1 + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + 1 - <span class=\"frac\"><span class=\"num\">143</span><span class=\"den\">30</span></span>) + (π + π - π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = 2a + 3b - <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + π</span>"}],
