    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> - 2 + a + √5 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - a + <span class=\"frac\"><span class=\"num\">137</span><span class=\"den\">30</span></span></span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = (-a + a - a) + (-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> - 2 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">137</span><span class=\"den\">30</span></span>) + √5</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = -a - 5 + √5</span>"}],
